 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    # The solid 2-line is the stop surface; objects move toward it.
    wall = None
    for r in range(h):
        if all(grid[r][c] == 2 for c in range(w)):
            wall = ('up' if r == 0 else 'down', r)
            break
    if wall is None:
        for c in range(w):
            if all(grid[r][c] == 2 for r in range(h)):
                wall = ('left' if c == 0 else 'right', c)
                break
    if wall is None:
        raise ValueError('No solid 2-line found')
    direction, _ = wall
    dr, dc = {'up': (-1, 0), 'down': (1, 0), 'left': (0, -1), 'right': (0, 1)}[direction]

    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (0, 2) or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                rr, cc = q.popleft()
                cells.append((rr, cc))
                for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen and grid[nr][nc] == color:
                        seen.add((nr, nc))
                        q.append((nr, nc))
            objects.append((color, cells))

    # Process closest-to-wall components first, so farther components stack on them.
    if direction == 'up':
        objects.sort(key=lambda obj: min(r for r, c in obj[1]))
    elif direction == 'down':
        objects.sort(key=lambda obj: -max(r for r, c in obj[1]))
    elif direction == 'left':
        objects.sort(key=lambda obj: min(c for r, c in obj[1]))
    else:
        objects.sort(key=lambda obj: -max(c for r, c in obj[1]))

    out = [[0] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2:
                out[r][c] = 2
    for color, cells in objects:
        placed = list(cells)
        while True:
            moved = [(r + dr, c + dc) for r, c in placed]
            if any(r < 0 or r >= h or c < 0 or c >= w or out[r][c] != 0 for r, c in moved):
                break
            placed = moved
        for r, c in placed:
            out[r][c] = color
    return out
